class Solution {
    public int minInsertions(String s){
        String reverse=new StringBuilder(s).reverse().toString();
        int n=s.length();
        int[] dp=new int[n+1];
        for(int i=1;i<=n;i++){
            int[] next=new int[n+1];
            for(int j=1;j<=n;j++)next[j]=s.charAt(i-1)==reverse.charAt(j-1)?dp[j-1]+1:Math.max(dp[j],next[j-1]);
            dp=next;
        }
        return n-dp[n];
    }
}

code.kotlin:
class Solution {
    fun minInsertions(s:String):Int{
        val reverse=s.reversed();
        val n=s.length;
        var dp=IntArray(n+1);
        for(i in 1..n){
            val next=IntArray(n+1);
            for(j in 1..n)next[j]=if(s[i-1]==reverse[j-1])dp[j-1]+1 else maxOf(dp[j],next[j-1]);
            dp=next
        };
        return n-dp[n]
    }
}

code.cpp:
class Solution {
    public: int minInsertions(string s){
        string reversed=s;
        reverse(reversed.begin(),reversed.end());
        int n=s.size();
        vector<int> dp(n+1);
        for(int i=1;i<=n;++i){
            vector<int> next(n+1);
            for(int j=1;j<=n;++j)next[j]=s[i-1]==reversed[j-1]?dp[j-1]+1:max(dp[j],next[j-1]);
            dp.swap(next);
        }
        return n-dp[n];
    }
};
